public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(SalesTable, FTDBookTable):
            this.ftdUpdateLinesBook();
            break;

    }
}

public void ftdUpdateLinesBook()
{
    SalesLine salesLine;

    while select forupdate salesLine
                where salesLine.SalesId == this.SalesId
    {
        salesLine.FTDBookTable = this.FTDBookTable;
        ttsbegin;
        if (salesLine.validateWrite())
        {
            salesLine.update();
        }
        ttscommit;
    }

    this.ftdResearchIfNeeded();
}

public void ftdResearchIfNeeded()
{
    FormDataSource formDataSource = FormDataUtil::getFormDataSource(this);

    if (formDataSource)
    {
        formDataSource.research(true);
    }
}

public Common ftdFantasyBookLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(FTDBookTable), _formReferenceControl);

    refTableLookup.parmQuery(this.ftdGetFantasyBookLookupQuery());
    refTableLookup.addLookupfield(fieldNum(FTDBookTable, Id));
    refTableLookup.addLookupfield(fieldNum(FTDBookTable, Name));
    refTableLookup.addLookupfield(fieldNum(FTDBookTable, Genre));
    refTableLookup.addLookupfield(fieldNum(FTDBookTable, Author));

    return refTableLookup.performFormLookup();
}
